insert into public.questions (id, pack_id, theme, type, prompt, unit, answer, items, year, subject, source, source_url, perishable, difficulty, status, verified_at, review_due_at, notes)
values
('cinema-p1-001', 'cinema', 'cinema', 'number'::public.question_type, 'En octobre 2026, combien de millions de dollars (non ajustés de l’inflation) a rapporté « Spider-Man: Brand New Day » lors de son premier week-end en Amérique du Nord, le meilleur démarrage de l’histoire ?', 'millions de dollars', 360.1, null, false, 'spiderman-bnd-ouverture', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_opening_weekend/', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'BOM : 360 091 572 $ (sortie 31/07/2026), devant Avengers: Endgame (357,1 M$). Record menacé par Avengers: Doomsday (déc. 2026).'),
('cinema-p1-002', 'cinema', 'cinema', 'number'::public.question_type, 'Mi-octobre 2026, combien de millions de dollars (non ajustés de l’inflation) a rapporté « Spider-Man: Brand New Day » en Amérique du Nord, le plus gros total de l’histoire sur ce marché ?', 'millions de dollars', 957.5, null, false, 'spiderman-bnd-domestique', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/', true, 3, 'review'::public.question_status, '2026-10-16', '2027-04-16', 'BOM au 16/10/2026 : 957 503 108 $, devant Star Wars VII (936,7 M$). Film peut-être encore à l’affiche : chiffre à figer. À relire : film encore à l''affiche, total en mouvement ; à figer après sa sortie des salles.'),
('cinema-p1-003', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Deadpool & Wolverine » (2024), le film interdit aux moins de 17 ans non accompagnés (R) le plus rentable de l’histoire ?', 'millions de dollars', 1338, null, false, 'deadpool-wolverine', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 1, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 338 073 645 $. Joker (1 079 M$) était le précédent record R.'),
('cinema-p1-004', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Barbie » (2023), le film le plus rentable réalisé par une femme seule ?', 'millions de dollars', 1447, null, false, 'barbie', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 1, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 447 138 421 $. Précision « seule » : La Reine des neiges II (1 454 M$) est coréalisé par Jennifer Lee et Chris Buck.'),
('cinema-p1-005', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Zootopie 2 » (2025), le film d’animation hollywoodien le plus rentable de l’histoire ?', 'millions de dollars', 1870, null, false, 'zootopie-2', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 1, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 870 309 291 $. Seul Ne Zha 2 (chinois, 2 271 M$) fait mieux en animation.'),
('cinema-p1-006', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Demon Slayer : La Forteresse infinie » (2025), le film japonais le plus rentable de l’histoire ?', 'millions de dollars', 793.6, null, false, 'demon-slayer-infinity-castle', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 3, 'published'::public.question_status, '2026-10-16', null, 'BOM : 793 594 078 $ (Mugen Train, précédent record : ~507 M$).'),
('cinema-p1-007', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Ça » (2017), le film d’horreur le plus rentable de l’histoire ?', 'millions de dollars', 719.8, null, false, 'ca-2017', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 2, 'published'::public.question_status, '2026-10-16', null, 'BOM : 719 766 009 $ (ressorties comprises). The Numbers donne ~701 M$ (écart < 3 %).'),
('cinema-p1-008', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Fahrenheit 9/11 » de Michael Moore, le documentaire le plus rentable de l’histoire (hors films de concert) ?', 'millions de dollars', 222.4, null, false, 'fahrenheit-911', 'Box Office Mojo', 'https://www.boxofficemojo.com/title/tt0361596/', false, 3, 'published'::public.question_status, '2026-10-16', null, 'BOM : 222 446 882 $. Exclusion des films-concerts (Taylor Swift: The Eras Tour, This Is It) qui le dépassent.'),
('cinema-p1-009', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « La Marche de l’empereur » (2005), le documentaire français le plus rentable de l’histoire ?', 'millions de dollars', 127.4, null, false, 'marche-empereur', 'Box Office Mojo', 'https://www.boxofficemojo.com/title/tt0428803/', false, 2, 'published'::public.question_status, '2026-10-16', null, 'BOM : 127 392 693 $ dont 77,4 M$ en Amérique du Nord.'),
('cinema-p1-010', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Intouchables » (2011), le film en langue française le plus rentable de l’histoire ?', 'millions de dollars', 426.6, null, false, 'intouchables-monde', 'Box Office Mojo', 'https://www.boxofficemojo.com/title/tt1675434/', false, 3, 'published'::public.question_status, '2026-10-16', null, 'BOM : 426 590 315 $ (dont 166 M$ en France). Lucy (EuropaCorp) a fait plus mais est tourné en anglais.'),
('cinema-p1-011', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Michael » (2026), le biopic le plus rentable de l’histoire ?', 'millions de dollars', 1028.7, null, false, 'michael-biopic', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 1, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 028 703 388 $ (devant Oppenheimer ~975 M$ et Bohemian Rhapsody ~911 M$). Sorti en avril 2026, exploitation quasi terminée.'),
('cinema-p1-012', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Le Roi lion » de 2019, le remake le plus rentable de l’histoire ?', 'millions de dollars', 1662, null, false, 'roi-lion-2019', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 1, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 662 020 819 $.'),
('cinema-p1-013', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Skyfall » (2012), le James Bond le plus rentable de l’histoire ?', 'millions de dollars', 1108.6, null, false, 'skyfall', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 2, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 108 594 137 $.'),
('cinema-p1-014', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Harry Potter et les Reliques de la Mort – 2e partie » (2011), le film le plus rentable de la saga ?', 'millions de dollars', 1343, null, false, 'harry-potter-reliques-2', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 1, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 342 945 821 $.'),
('cinema-p1-015', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Star Wars : Le Réveil de la Force » (2015), le film le plus rentable de la saga Star Wars ?', 'millions de dollars', 2071, null, false, 'star-wars-7', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 1, 'published'::public.question_status, '2026-10-16', null, 'BOM : 2 071 310 218 $.'),
('cinema-p1-016', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Aquaman » (2018), le film de l’univers DC le plus rentable de l’histoire ?', 'millions de dollars', 1152, null, false, 'aquaman', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 2, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 152 028 393 $. The Dark Knight Rises (1 085 M$) et Joker (1 079 M$) derrière.'),
('cinema-p1-017', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « Top Gun: Maverick » (2022), le plus gros succès de la carrière de Tom Cruise ?', 'millions de dollars', 1503, null, false, 'top-gun-maverick', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', false, 1, 'published'::public.question_status, '2026-10-16', null, 'BOM : 1 503 260 455 $.'),
('cinema-p1-018', 'cinema', 'cinema', 'number'::public.question_type, 'Mi-octobre 2026, combien de millions de dollars (non ajustés de l’inflation) a rapporté dans le monde « L’Odyssée » (2026), le plus gros succès de Christopher Nolan ?', 'millions de dollars', 1783, null, false, 'the-odyssey', 'Box Office Mojo', 'https://www.boxofficemojo.com/chart/top_lifetime_gross/?area=XWW', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'BOM au 16/10/2026 : 1 782 966 184 $ (sortie juillet 2026, Oppenheimer ~975 M$). Peut encore évoluer légèrement.'),
('cinema-p1-019', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions d’entrées a réalisé « Titanic » dans les salles françaises (ressorties comprises), le film le plus vu de l’histoire en France ?', 'millions d’entrées', 22.3, null, false, 'titanic-entrees-france', 'Wikipédia (données CBO / CNC)', 'https://fr.wikipedia.org/wiki/Liste_des_plus_gros_succès_du_box-office_en_France', false, 1, 'published'::public.question_status, '2026-10-16', null, '22 320 788 entrées ressorties comprises ; la 1re exploitation seule est souvent citée à ~21,8 M (écart ~2 %).'),
('cinema-p1-020', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions d’entrées a réalisé en 2024 « Un p’tit truc en plus » d’Artus, le film le plus vu en salles en France cette année-là ?', 'millions d’entrées', 10.31, null, false, 'un-ptit-truc-en-plus', 'CNC', 'https://www.cnc.fr/professionnels/communiques-de-presse/avec-plus-de-181-millions-dentrees-en-2024-les-salles-francaises-confirment-la-situation-exceptionnelle-de-la-france-dans-le-paysage-du-cinema-mondial_2318147', false, 2, 'published'::public.question_status, '2026-10-16', null, 'CNC, top 10 2024 arrêté au 29/12/2024 : 10,31 M d’entrées (cumul total ~10,8 M avec 2025).'),
('cinema-p1-021', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions d’entrées ont été vendues dans les cinémas français en 2011, la meilleure année de fréquentation depuis 1966 ?', 'millions d’entrées', 217.2, null, false, 'frequentation-2011', 'CNC', 'https://www.cnc.fr/professionnels/communiques-de-presse/une-annee-record-pour-la-frequentation-avec-plus-de-213-millions-dentrees-en-salles-de-cinema_1104651', false, 2, 'published'::public.question_status, '2026-10-16', null, 'CNC : 2011 = 217,2 M ; 2019 = 213,3 M ; 1966 = 234,2 M.'),
('cinema-p1-022', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions d’entrées a réalisé « Blanche-Neige et les Sept Nains » en France (ressorties comprises), le dessin animé le plus vu de l’histoire dans les salles françaises ?', 'millions d’entrées', 18.4, null, false, 'blanche-neige-entrees', 'Wikipédia (données CBO / CNC)', 'https://fr.wikipedia.org/wiki/Liste_des_plus_gros_succès_du_box-office_en_France', false, 3, 'published'::public.question_status, '2026-10-16', null, '18 353 225 entrées cumulées depuis 1938, 4e du classement général. Chiffres anciens reconstitués : à relire.'),
('cinema-p1-023', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de millions de téléspectateurs ont regardé « L’Ours » de Jean-Jacques Annaud en février 1992, la meilleure audience de l’histoire pour un film à la télévision française ?', 'millions de téléspectateurs', 16.4, null, false, 'lours-audience-tv', 'Puremédias (Médiamétrie)', 'https://www.ozap.com/actu/audiences-bienvenue-chtis-come-back-capital-village-francais/380860', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Puremédias : près de 16,4 M (68 % de PDA) ; Europe 1 cite 16,3 M. Record pour un film.'),
('cinema-p1-024', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de places compte la Grande Salle du Grand Rex à Paris, la plus grande salle de cinéma d’Europe ?', 'places', 2702, null, false, 'grand-rex', 'Le Grand Rex / presse', 'https://www.nomadotravel.app/fr/attractions/le-grand-rex', false, 2, 'review'::public.question_status, '2026-10-16', null, '2 702 places selon la plupart des sources (certaines arrondissent à 2 700–2 800). À relire : source non officielle (site de voyage) ; confirmer sur le site du Grand Rex.'),
('cinema-p1-025', 'cinema', 'cinema', 'number'::public.question_type, 'Combien d’épisodes de « Plus belle la vie » ont été diffusés sur France 3 de 2004 à 2022, le feuilleton quotidien le plus long de l’histoire de la télévision française ?', 'épisodes', 4665, null, false, 'plus-belle-la-vie', 'Puremédias / La Voix du Nord', 'https://www.ozap.com/actu/-plus-belle-la-vie-quels-acteurs-ont-le-plus-joue-dans-le-feuilleton-de-france-3/623966', false, 2, 'published'::public.question_status, '2026-10-16', null, '18 saisons, 4 665 épisodes sur France 3 (hors suite sur TF1 depuis 2024).'),
('cinema-p1-026', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de nominations aux Oscars a obtenu « Sinners » de Ryan Coogler en 2026, le film le plus nommé de l’histoire ?', 'nominations', 16, null, false, 'sinners-nominations', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2026/1/sinners-breaks-decades-long-record-for-most-oscar-nominations-including-best-picture', false, 1, 'published'::public.question_status, '2026-10-16', null, '16 nominations (98e cérémonie), record précédent : 14 (Eve, Titanic, La La Land).'),
('cinema-p1-027', 'cinema', 'cinema', 'number'::public.question_type, 'En octobre 2026, combien de nominations aux Oscars compte le compositeur John Williams, la personne vivante la plus nommée de l’histoire ?', 'nominations', 54, null, false, 'john-williams-nominations', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/most-oscar-nominations-living-person', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', '54 nominations (dernière en janv. 2024), 5 victoires. Pas de nomination en 2025-2026 trouvée ; Disclosure Day (2026) pourrait en ajouter une en 2027.'),
('cinema-p1-028', 'cinema', 'cinema', 'number'::public.question_type, 'En octobre 2026, combien de nominations aux Oscars compte Meryl Streep, l’interprète la plus nommée de l’histoire ?', 'nominations', 21, null, false, 'meryl-streep-nominations', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/74363-most-oscar-nominations-for-an-actress', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', '21 nominations (la dernière pour Pentagon Papers, 2018), 3 victoires.'),
('cinema-p1-029', 'cinema', 'cinema', 'number'::public.question_type, 'Quel âge avait Jessica Tandy en 1990 quand elle a reçu l’Oscar de la meilleure actrice pour « Miss Daisy et son chauffeur », la plus âgée de l’histoire dans cette catégorie ?', 'ans', 80, null, false, 'jessica-tandy', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/oldest-oscar-winner-as-best-actress', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 80 ans et 295 jours.'),
('cinema-p1-030', 'cinema', 'cinema', 'number'::public.question_type, 'Quel âge avait Marlee Matlin en 1987 quand elle a reçu l’Oscar de la meilleure actrice pour « Les Enfants du silence », la plus jeune lauréate de l’histoire dans cette catégorie ?', 'ans', 21, null, false, 'marlee-matlin', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/74355-youngest-oscar-winner-for-best-actress', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 21 ans et 218 jours.'),
('cinema-p1-031', 'cinema', 'cinema', 'number'::public.question_type, 'Quel âge avait Damien Chazelle en 2017 quand il a reçu l’Oscar du meilleur réalisateur pour « La La Land », le plus jeune lauréat de l’histoire dans cette catégorie ?', 'ans', 32, null, false, 'damien-chazelle', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/463825-youngest-winner-of-the-academy-award-for-best-director', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 32 ans et 38 jours.'),
('cinema-p1-032', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de minutes a duré la cérémonie des Oscars de 2002, la plus longue de l’histoire ?', 'minutes', 263, null, false, 'oscars-2002-duree', 'KHOU (Oscars by the numbers)', 'https://www.khou.com/article/entertainment/oscars-by-the-numbers-breaking-down-the-biggest-night-in-hollywood/285-9a238839-fd8f-4873-ad52-cb62a1cf6cf2', false, 2, 'published'::public.question_status, '2026-10-16', null, '4 h 23 min selon la plupart des sources (une seule source ancienne donne 4 h 16, écart < 3 %).'),
('cinema-p1-033', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de minutes a duré la toute première cérémonie des Oscars en 1929, la plus courte de l’histoire ?', 'minutes', 15, null, false, 'oscars-1929-duree', '/Film', 'https://www.slashfilm.com/1763474/first-oscars-ceremony-facts', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Environ 15 minutes : les lauréats étaient connus d’avance, pas de retransmission.'),
('cinema-p1-034', 'cinema', 'cinema', 'number'::public.question_type, 'Selon le Guinness, combien de secondes Beatrice Straight apparaît-elle à l’écran dans « Network » (1976), le rôle le plus court jamais récompensé par un Oscar d’interprétation ?', 'secondes', 340, null, false, 'beatrice-straight', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/91097-shortest-role-to-win-an-acting-oscar', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Guinness et TCM : 5 min 40 s = 340 s. Une source isolée (Far Out) donne 5 min 02 : d’où le « selon le Guinness ».'),
('cinema-p1-035', 'cinema', 'cinema', 'number'::public.question_type, 'Quel âge avait Steven Soderbergh en 1989 quand il a remporté la Palme d’or pour « Sexe, Mensonges et Vidéo », le plus jeune réalisateur à l’avoir remportée seul ?', 'ans', 26, null, false, 'soderbergh-palme', 'Wikipédia / Chicago Reader', 'https://en.wikipedia.org/wiki/Sex,_Lies,_and_Videotape', false, 2, 'published'::public.question_status, '2026-10-16', null, '26 ans. « Seul » : Louis Malle était plus jeune en 1956 mais coréalisait avec Cousteau.'),
('cinema-p1-036', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de marches faut-il gravir pour accéder au Palais des Festivals de Cannes, la montée des marches la plus célèbre du cinéma ?', 'marches', 24, null, false, 'cannes-marches', 'Festival de Cannes', 'https://www.festival-cannes.com/cannes-focus/les-secrets-du-tapis-rouge-du-festival-de-cannes/', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Site officiel : 24 marches et 60 m de tapis rouge.'),
('cinema-p1-037', 'cinema', 'cinema', 'number'::public.question_type, 'Combien d’heures dure « Logistics » (2012), le film le plus long jamais réalisé selon le Guinness ?', 'heures', 857, null, false, 'logistics', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/69763-longest-film-made', false, 3, 'published'::public.question_status, '2026-10-16', null, '857 h = 35 jours et 17 heures (durée IMDb reprise par le Guinness).'),
('cinema-p1-038', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de minutes dure la version longue du « Seigneur des anneaux : Le Retour du roi », le plus long film de la trilogie ?', 'minutes', 263, null, false, 'retour-du-roi-version-longue', 'IMDb', 'https://www.imdb.com/title/tt0167260/technical', false, 2, 'published'::public.question_status, '2026-10-16', null, 'IMDb : 263 min (version longue Blu-ray), 201 min en salles. Certaines sources donnent 251–253 min sans le générique du fan-club (écart ~4 %).'),
('cinema-p1-039', 'cinema', 'cinema', 'number'::public.question_type, 'Combien de milliers de figurants ont participé à la scène des funérailles de « Gandhi » (1982), le record de figurants de l’histoire du cinéma ?', 'milliers', 300, null, false, 'gandhi-figurants', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/69811-most-film-extras', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : plus de 300 000 (200 000 bénévoles + 94 560 payés), certaines sources disent 400 000.'),
