('musique-p1-042', 'musique', 'musique', 'number'::public.question_type, 'À quelle profondeur (en mètres) le groupe Miners and Sons a-t-il joué en 2024 dans la mine Kidd de Timmins (Canada), le concert le plus profond du monde selon le Guinness ?', 'm', 2700, null, false, 'concert-profond', 'Guinness World Records (via CBC)', 'https://www.cbc.ca/1.7384952', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Niveau 9 000 pieds, environ 2 700 m (2 743 m en conversion exacte, écart 1,6 %). Ancien record : 1 893,8 m (2020).'),
('musique-p1-043', 'musique', 'musique', 'number'::public.question_type, 'Selon le Guinness, combien de spectateurs (en millions) Rod Stewart a-t-il réunis sur la plage de Copacabana le 31 décembre 1994, le concert gratuit le plus fréquenté de l’histoire ?', 'millions de spectateurs', 3.5, null, false, 'rod-stewart-copacabana', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/73085-largest-free-rock-concert-attendance', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Au moins 3,5 M (chiffre incluant probablement des spectateurs venus pour le feu d’artifice).'),
('musique-p1-044', 'musique', 'musique', 'number'::public.question_type, 'Combien de mots compte « Rap God » d’Eminem, le tube contenant le plus de mots selon le Guinness ?', 'mots', 1560, null, false, 'rap-god', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/112754-most-words-in-a-hit-single', false, 2, 'published'::public.question_status, '2026-10-16', null, '1 560 mots en 6 min 4 s, soit 4,28 mots/s.'),
