('musique-p1-055', 'musique', 'musique', 'ranking'::public.question_type, 'Classe ces artistes du moins au plus de Grammy Awards remportés', 'Grammys', null, '[{"label":"Vladimir Horowitz","value":25},{"label":"Pierre Boulez","value":26},{"label":"Quincy Jones","value":28},{"label":"Georg Solti","value":31}]'::jsonb, false, 'grammys-records', 'Recording Academy (grammy.com)', 'https://www.grammy.com/news/who-are-the-top-grammy-awards-winners-of-all-time', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Totaux définitifs (tous décédés). Beyoncé (35) exclue : sujet existant.'),
('musique-p1-056', 'musique', 'musique', 'ranking'::public.question_type, 'Classe ces albums du moins au plus certifiés par la RIAA aux États-Unis', 'millions d’unités', null, '[{"label":"Led Zeppelin – Led Zeppelin IV","value":24},{"label":"AC/DC – Back in Black","value":27},{"label":"Eagles – Hotel California","value":28},{"label":"Eagles – Their Greatest Hits 1971-1975","value":40}]'::jsonb, false, 'riaa-albums', 'RIAA', 'https://www.riaa.com/gold-platinum/?tab_active=top_tallies&ttt=T1A', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Top 100 albums RIAA consulté le 16/10/2026 (Eagles 40× platine depuis janvier 2026). Thriller (34) écarté pour éviter le doublon.'),
('musique-p1-057', 'musique', 'musique', 'ranking'::public.question_type, 'Classe ces artistes du moins au plus de titres n°1 au Billboard Hot 100', 'titres n°1', null, '[{"label":"Madonna","value":12},{"label":"Michael Jackson","value":13},{"label":"Mariah Carey","value":19},{"label":"The Beatles","value":20}]'::jsonb, false, 'hot100-numeros-un', 'Billboard', 'https://www.billboard.com/lists/artists-most-number-one-hits-all-time-hot-100/', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Totaux 2026 ; Taylor Swift (15), Rihanna et Drake (14) écartés car encore évolutifs.'),
('musique-p1-058', 'musique', 'musique', 'ranking'::public.question_type, 'Classe ces instruments du moins cher au plus cher vendu aux enchères', 'millions de $', null, '[{"label":"Guitare Martin D-18E de Kurt Cobain (2020)","value":6.01},{"label":"Violon Stradivarius « Joachim-Ma » (2025)","value":11.3},{"label":"Guitare « Black Strat » de David Gilmour (2026)","value":14.55},{"label":"Violon Stradivarius « Lady Blunt » (2011)","value":15.9}]'::jsonb, false, 'instruments-chers', 'Ultimate Classic Rock / Guinness', 'https://ultimateclassicrock.com/david-gilmour-guitar-smashes-auction-record-selling-for-14-5-million/', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Black Strat : 14,55 M$ chez Christie’s le 12/03/2026 (collection Jim Irsay), nouveau record pour une guitare. Lady Blunt : record Guinness pour un instrument. Joachim-Ma : Sotheby’s, 7/02/2025. Cobain : Guinness 2020.'),
('musique-p1-059', 'musique', 'musique', 'ranking'::public.question_type, 'Classe ces tournées de la moins à la plus rentable (recettes totales)', 'millions de $', null, '[{"label":"Rolling Stones – A Bigger Bang (2005-2007)","value":558},{"label":"U2 – 360° Tour (2009-2011)","value":736.4},{"label":"Ed Sheeran – ÷ Tour (2017-2019)","value":776.2},{"label":"Elton John – Farewell Yellow Brick Road (2018-2023)","value":939.1}]'::jsonb, false, 'tournees-recettes', 'Billboard Boxscore / Guinness', 'https://guinnessworldrecords.com/news/2023/2/elton-john-going-out-with-a-bang-as-final-tour-becomes-highest-grossing-ever-737203', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Elton John 939,1 M$ (bilan final, IQ Magazine) ; Sheeran 776,2 M$ (Guinness) ; U2 736,4 M$ et Stones 558 M$ (Billboard). Tournées terminées.'),
('musique-p1-060', 'musique', 'musique', 'ranking'::public.question_type, 'Classe ces albums du moins au plus vendu en première semaine en France', 'exemplaires', null, '[{"label":"PNL – Deux frères (2019)","value":113214},{"label":"Jul – TP sur TP (2025)","value":134482},{"label":"Johnny Hallyday – À la vie, à la mort ! (2002)","value":305634},{"label":"Johnny Hallyday – Mon pays c’est l’amour (2018)","value":780177}]'::jsonb, false, 'demarrages-france', 'SNEP / GfK (via Charts in France)', 'https://www.chartsinfrance.net/actualite/news-108439.html', false, 2, 'published'::public.question_status, '2026-10-16', null, '780 177 : record SNEP/GfK. 305 634 (Booska-P ; ~306 000 Chartmasters). Jul 134 482 (Purebreak, ventes groupées avec billets de concert). PNL 113 214 (Booska-P).'),
('jo-p1-001', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles la France a-t-elle remportées aux JO de Paris 2024, son plus gros total depuis 1900 ?', 'médailles', 64, null, false, 'france-medailles-paris2024', 'Olympics.com (tableau des médailles)', 'https://www.olympics.com/en/olympic-games/paris-2024/medals', false, 1, 'published'::public.question_status, '2026-10-16', null, '16 or, 26 argent, 22 bronze. Meilleur total depuis 1900 (112 selon Olympedia). Fait figé.'),
('jo-p1-002', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles d''or la France a-t-elle gagnées à Paris 2024, sa meilleure récolte de titres depuis 1900 ?', 'médailles d''or', 16, null, false, 'france-or-paris2024', 'Olympics.com (tableau des médailles)', 'https://www.olympics.com/en/olympic-games/paris-2024/medals', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Précédent meilleur bilan d''or depuis 1900 : 15 (Atlanta 1996), selon Olympedia.'),
('jo-p1-003', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles d''or ont remportées les États-Unis à Paris 2024, nation la plus titrée à égalité parfaite avec la Chine ?', 'médailles d''or', 40, null, false, 'usa-chine-or-paris2024', 'Olympics.com (tableau des médailles)', 'https://www.olympics.com/en/olympic-games/paris-2024/medals', false, 1, 'published'::public.question_status, '2026-10-16', null, 'États-Unis 40-44-42 (126), Chine 40-27-24 (91) : les USA passent devant à l''argent.'),
('jo-p1-004', 'jo', 'jo', 'number'::public.question_type, 'Combien de millions de billets ont été vendus pour les JO de Paris 2024, record absolu pour des Jeux olympiques ?', 'millions de billets', 9.5, null, false, 'billets-paris2024', 'CIO (chiffres clés Paris 2024)', 'https://www.olympics.com/en/news/paris-2024-paralympic-games-key-figures', false, 1, 'published'::public.question_status, '2026-10-16', null, '9,5 millions pour les JO (+2,5 M pour les Paralympiques). Ancien record : Atlanta 1996 (8,3 M).'),
('jo-p1-005', 'jo', 'jo', 'number'::public.question_type, 'Combien pèse une médaille d''or de Paris 2024, l''une des plus lourdes de l''histoire avec son morceau de tour Eiffel ?', 'g', 529, null, false, 'medaille-or-poids', 'Olympics.com (présentation des médailles)', 'https://www.olympics.com/en/news/paris-2024-olympic-paralympic-medals-reveal-eiffel-tower', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Or 529 g, argent 525 g, bronze 455 g ; 85 mm de diamètre, 18 g de fer d''origine de la tour Eiffel.'),
('jo-p1-006', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles ont été frappées pour les JO et Paralympiques de Paris 2024, chacune sertie d''un fragment de la tour Eiffel, le monument le plus célèbre de France ?', 'médailles', 5084, null, false, 'medailles-produites-paris2024', 'Olympics.com (présentation des médailles)', 'https://www.olympics.com/en/news/paris-2024-olympic-paralympic-medals-reveal-eiffel-tower', false, 3, 'published'::public.question_status, '2026-10-16', null, '5 084 médailles (JO + Paralympiques), chiffre officiel concordant ITF/NBC ; 18 g de fer de la tour Eiffel dans chacune.'),
('jo-p1-007', 'jo', 'jo', 'number'::public.question_type, 'Combien d''épreuves (titres olympiques) comptait le programme de Paris 2024, le plus grand événement sportif jamais organisé en France ?', 'épreuves', 329, null, false, 'epreuves-paris2024', 'Olympedia (Paris 2024)', 'https://www.olympedia.org/editions/63', false, 2, 'published'::public.question_status, '2026-10-16', null, '329 épreuves dans 32 sports (Olympedia et Olympics.com concordent).'),
('jo-p1-008', 'jo', 'jo', 'number'::public.question_type, 'Combien de comités nationaux olympiques étaient représentés à Paris 2024, le plus grand événement sportif de la planète ?', 'comités', 206, null, false, 'cno-paris2024', 'Olympedia (Paris 2024) / CIO', 'https://www.olympedia.org/editions/63', false, 2, 'published'::public.question_status, '2026-10-16', null, '206 CNO, plus l''équipe olympique des réfugiés et les athlètes neutres (AIN).'),
('jo-p1-009', 'jo', 'jo', 'number'::public.question_type, 'Environ combien d''athlètes ont participé aux JO de Paris 2024, les premiers à parité parfaite hommes-femmes ?', 'athlètes', 10500, null, false, 'athletes-paris2024', 'CIO', 'https://www.olympics.com/ioc/news/paris-2024-to-unite-the-world-in-peaceful-competition-and-to-leave-a-lasting-social-legacy', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Chiffre officiel CIO : environ 10 500 ; Olympedia recense 10 762 participants (+2,5 %, dans la tolérance).'),
('jo-p1-010', 'jo', 'jo', 'number'::public.question_type, 'Combien de sports figuraient au programme de Paris 2024, les Jeux qui ont accueilli le breaking pour la toute première fois ?', 'sports', 32, null, false, 'sports-paris2024', 'Olympics.com', 'https://www.olympics.com/en/news/24-things-we-already-know-about-the-olympic-games-paris-2024', false, 1, 'published'::public.question_status, '2026-10-16', null, '32 sports, 48 disciplines, 329 épreuves.'),
('jo-p1-011', 'jo', 'jo', 'number'::public.question_type, 'Combien de comités nationaux ont remporté au moins une médaille à Paris 2024, où la Dominique et Sainte-Lucie ont décroché leur tout premier titre ?', 'pays', 91, null, false, 'nations-medaillees-paris2024', 'Olympics.com (premières médailles nationales)', 'https://www.olympics.com/en/news/paris-2024-olympics-nations-won-first-ever-medal-at-the-games', false, 2, 'published'::public.question_status, '2026-10-16', null, '91 CNO + l''équipe des réfugiés (bronze de Cindy Ngamba). Attention : Tokyo 2020 en comptait 93, ce n''est pas un record.'),
('jo-p1-012', 'jo', 'jo', 'number'::public.question_type, 'Léon Marchand a nagé le 200 m 4 nages de Paris 2024 en 1 min et combien de secondes, le record olympique le plus rapide de l''histoire ?', 's', 54.06, null, false, 'marchand-200-4n', 'NBC News / résultats officiels', 'https://www.nbcnews.com/sports/olympics/leon-marchand-fourth-gold-medal-rcna164937', true, 3, 'published'::public.question_status, '2026-10-16', '2027-04-16', '1 min 54 s 06 (OR, ancien : Phelps 1:54.23). Réponse = secondes après la minute.'),
('jo-p1-013', 'jo', 'jo', 'number'::public.question_type, 'Combien de combats d''affilée Teddy Riner, le judoka le plus titré de l''histoire, a-t-il gagnés entre 2010 et 2020 ?', 'victoires', 154, null, false, 'riner-serie', 'Olympics.com (profil Teddy Riner)', 'https://stacy.olympics.com/tokyo-2020/olympic-games/en/results/judo/athlete-profile-n1403689-riner-teddy.htm', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Pas un record absolu (Yasuhiro Yamashita : 203). Série stoppée par Kokoro Kageura au Grand Slam de Paris, février 2020.'),
('jo-p1-014', 'jo', 'jo', 'number'::public.question_type, 'À quel âge Teddy Riner a-t-il conquis l''or des +100 kg à Paris 2024, devenant le judoka le plus médaillé de l''histoire olympique ?', 'ans', 35, null, false, 'riner-age-paris2024', 'Olympics.com', 'https://www.olympics.com/en/news/paris-2024-judo-teddy-riner-takes-gold-at-100kg-most-decorated-olympic-judoka', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Né le 7 avril 1989, titre le 2 août 2024.'),
('jo-p1-015', 'jo', 'jo', 'number'::public.question_type, 'Combien de bénévoles ont été retenus pour les JO de Paris 2024, sur environ 300 000 candidatures, pour le plus grand événement jamais organisé en France ?', 'bénévoles', 45000, null, false, 'benevoles-paris2024', 'Olympics.com (programme des volontaires)', 'https://www.olympics.com/en/news/uniforms-volunteers-paris-2024-decathlon-presentation-show', false, 2, 'published'::public.question_status, '2026-10-16', null, '45 000 volontaires sélectionnés (300 000 candidatures, 190 pays). Chiffre concordant avec l''Assemblée nationale.'),
('jo-p1-016', 'jo', 'jo', 'number'::public.question_type, 'Combien de lits comptait le Village olympique de Paris 2024 pendant les JO, le plus grand « hôtel » de l''été ?', 'lits', 14250, null, false, 'village-lits', 'Olympics.com (chiffres clés du Village)', 'https://www.olympics.com/en/news/paris-2024-games-key-figures-village-olympic-paralympic', false, 3, 'published'::public.question_status, '2026-10-16', null, '14 250 lits, 82 bâtiments, ~3 000 appartements ; environ 9 000 lits pendant les Paralympiques.'),
('jo-p1-017', 'jo', 'jo', 'number'::public.question_type, 'Combien de coureurs amateurs ont pris part au Marathon pour tous de Paris 2024, la toute première course de masse de l''histoire des Jeux ?', 'coureurs', 40048, null, false, 'marathon-pour-tous', 'NBC / organisateurs Paris 2024', 'https://nbcchicago.com/paris-2024-summer-olympics/what-is-the-marathon-for-all-featured-in-the-olympic-closing-ceremony/3518875', false, 2, 'published'::public.question_status, '2026-10-16', null, '20 024 sur le marathon + 20 024 sur le 10 km, parité 50/50. Première course de masse intégrée aux Jeux.'),
('jo-p1-018', 'jo', 'jo', 'number'::public.question_type, 'En quelle année a été lancé le Belem, plus vieux trois-mâts barque d''Europe, qui a apporté la flamme de Paris 2024 à Marseille ?', '', 1896, null, true, 'belem', 'Olympics.com (le Belem)', 'https://www.olympics.com/en/news/the-belem-everything-you-need-to-know-about-the-iconic-ship', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Lancé le 10 juin 1896 à Nantes — l''année des premiers JO modernes.'),
('jo-p1-019', 'jo', 'jo', 'number'::public.question_type, 'Combien de jours a duré le relais de la flamme de Paris 2024 en France, après sa traversée à bord du plus vieux trois-mâts barque d''Europe ?', 'jours', 68, null, false, 'relais-flamme-paris2024', 'Olympics.com (parcours du relais)', 'https://www.olympics.com/en/news/paris-2024-olympic-torch-relay-route-unveiled-', false, 2, 'published'::public.question_status, '2026-10-16', null, '68 jours officiellement (du 8 mai au 26 juillet ; certaines sources disent 69 en comptant le prologue — écart < 2 %).'),
('jo-p1-020', 'jo', 'jo', 'number'::public.question_type, 'Combien de mètres mesurait la vasque-montgolfière de Paris 2024 aux Tuileries, la première vasque olympique volante ?', 'm', 30, null, false, 'vasque-ballon', 'LightZoomLumière / Paris 2024', 'https://www.lightzoomlumiere.fr/realisation/vasque-olympique-montgolfiere-paris-2024-eclairage-led-brume-eau/', false, 2, 'published'::public.question_status, '2026-10-16', null, '30 m de haut, 7 m de diamètre ; elle s''élevait à environ 60 m chaque soir.'),
('jo-p1-021', 'jo', 'jo', 'number'::public.question_type, 'Combien de milliards d''euros a coûté le plan baignade de la Seine, le plus gros chantier de dépollution lié aux JO de Paris 2024 ?', 'milliards d''euros', 1.4, null, false, 'seine-plan-baignade', 'L''Avenir / AFP', 'https://www.lavenir.net/sports/2024/07/30/depolluer-la-seine-un-projet-a-14-milliard-qui-tombe-a-leau-743EHUFTH5D3DKM6VYONKAVCUU/', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Environ 1,4 milliard € (État, Ville de Paris, collectivités) ; chiffre concordant dans toutes les sources.'),
('jo-p1-022', 'jo', 'jo', 'number'::public.question_type, 'À combien de kilomètres de Paris se trouvait Teahupo''o, le site de surf de Paris 2024 et le plus éloigné de sa ville hôte de toute l''histoire olympique ?', 'km', 15700, null, false, 'teahupoo', 'NPR', 'https://www.npr.org/2024/07/24/nx-s1-5050686/olympics-surfing-tahiti', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Environ 15 700 km (15 716 à 15 730 selon les sources).'),
('jo-p1-023', 'jo', 'jo', 'number'::public.question_type, 'En combien de secondes Aleksandra Mirosław a-t-elle escaladé le mur de vitesse de 15 m aux JO de Paris 2024, record du monde le plus rapide alors jamais réalisé ?', 's', 6.06, null, false, 'miroslaw-escalade', 'Guinness World Records', 'https://guinnessworldrecords.com/world-records/87655-fastest-15-m-speed-climb-female', false, 2, 'published'::public.question_status, '2026-10-16', null, '6,06 s en qualifications le 5 août 2024 (record du monde à ce moment ; battu depuis). Énoncé figé sur Paris 2024.'),
('jo-p1-024', 'jo', 'jo', 'number'::public.question_type, 'Quel est le record olympique du lancer du disque, le plus long jet de l''histoire des Jeux, établi par Rojé Stona à Paris 2024 (valable en 2026) ?', 'm', 70, null, false, 'disque-record-olympique', 'Olympedia (records olympiques)', 'https://www.olympedia.org/records/sport/ATH', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', '70,00 m le 7 août 2024.'),
('jo-p1-025', 'jo', 'jo', 'number'::public.question_type, 'Quel est le record olympique du lancer du marteau, le plus ancien record olympique des lancers masculins (Sergueï Litvinov, Séoul 1988) ?', 'm', 84.8, null, false, 'marteau-record-olympique', 'Olympedia (records olympiques)', 'https://www.olympedia.org/records/sport/ATH', true, 3, 'published'::public.question_status, '2026-10-16', '2027-04-16', '84,80 m le 26 septembre 1988, toujours record olympique en 2026.'),
('jo-p1-026', 'jo', 'jo', 'number'::public.question_type, 'Quel est le record olympique du triple saut, la plus longue triple foulée jamais vue aux Jeux (Kenny Harrison, Atlanta 1996) ?', 'm', 18.09, null, false, 'triple-saut-record-olympique', 'Olympedia (records olympiques)', 'https://www.olympedia.org/records/sport/ATH', true, 3, 'published'::public.question_status, '2026-10-16', '2027-04-16', '18,09 m, toujours record olympique en 2026.'),
('jo-p1-027', 'jo', 'jo', 'number'::public.question_type, 'En combien de secondes la Jamaïque de Bolt a-t-elle couru le 4 × 100 m à Londres 2012, le relais le plus rapide de l''histoire ?', 's', 36.84, null, false, 'relais-4x100-record', 'Olympedia (records olympiques)', 'https://www.olympedia.org/records/sport/ATH', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', '36 s 84, record olympique et du monde toujours valable en 2026.'),
('jo-p1-028', 'jo', 'jo', 'number'::public.question_type, 'En combien de secondes Wayde van Niekerk a-t-il couru le 400 m à Rio 2016, le tour de piste le plus rapide de l''histoire ?', 's', 43.03, null, false, '400m-van-niekerk', 'Olympedia (records olympiques)', 'https://www.olympedia.org/records/sport/ATH', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', '43 s 03, record olympique et du monde toujours valable en 2026.'),
('jo-p1-029', 'jo', 'jo', 'number'::public.question_type, 'Quelle distance a sautée James Connolly au triple saut en 1896, la toute première victoire olympique de l''ère moderne ?', 'm', 13.71, null, false, 'connolly-1896', 'Olympics.com', 'https://olympics.com/en/news/connolly-takes-a-leap-into-the-history-books', false, 3, 'published'::public.question_status, '2026-10-16', null, '13,71 m le 6 avril 1896 ; à comparer aux 18,09 m du record olympique.'),
('jo-p1-030', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles olympiques a remportées Larissa Latynina, la gymnaste la plus médaillée de l''histoire ?', 'médailles', 18, null, false, 'latynina', 'Olympedia (médailles par athlète)', 'https://www.olympedia.org/statistics/medal/athlete', false, 2, 'published'::public.question_status, '2026-10-16', null, '9 or, 5 argent, 4 bronze (1956-1964). 2e au total derrière Phelps.'),
('jo-p1-031', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles olympiques Katie Ledecky, la nageuse la plus médaillée de l''histoire, comptait-elle en octobre 2026 ?', 'médailles', 14, null, false, 'ledecky', 'Olympedia (médailles par athlète)', 'https://www.olympedia.org/statistics/medal/athlete', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', '9 or, 4 argent, 1 bronze après Paris 2024 ; prochaine échéance LA 2028.'),
('jo-p1-032', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles paralympiques a remportées la nageuse Trischa Zorn, l''athlète la plus médaillée de l''histoire des Paralympiques ?', 'médailles', 55, null, false, 'zorn', 'Comité international paralympique', 'https://www.paralympic.org/feature/no-21-zorn-s-55th-and-final-medal', false, 2, 'published'::public.question_status, '2026-10-16', null, '41 or, 9 argent, 5 bronze (1980-2004).'),
('jo-p1-033', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles d''or la Norvège a-t-elle remportées à Milan-Cortina 2026, record absolu pour une nation aux Jeux d''hiver ?', 'médailles d''or', 18, null, false, 'norvege-or-milan', 'Olympics.com (tableau des médailles)', 'https://www.olympics.com/en/milano-cortina-2026/medals', false, 2, 'published'::public.question_status, '2026-10-16', null, '18 or (ancien record : 16, Norvège à Pékin 2022) ; 41 médailles au total.'),
('jo-p1-034', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles la France a-t-elle remportées à Milan-Cortina 2026, son record absolu aux Jeux d''hiver ?', 'médailles', 23, null, false, 'france-milan-cortina', 'Olympics.com (tableau des médailles)', 'https://www.olympics.com/en/milano-cortina-2026/medals', false, 1, 'published'::public.question_status, '2026-10-16', null, '8 or, 9 argent, 6 bronze ; 6e nation. Ancien record : 15 (Sotchi 2014, PyeongChang 2018).'),
('jo-p1-035', 'jo', 'jo', 'number'::public.question_type, 'Combien d''athlètes ont participé aux JO d''Albertville 1992, les plus grands Jeux d''hiver organisés en France ?', 'athlètes', 1801, null, false, 'albertville-athletes', 'Olympedia (Albertville 1992)', 'https://www.olympedia.org/editions/44', false, 3, 'published'::public.question_status, '2026-10-16', null, '1 801 athlètes de 64 pays, 57 épreuves (Olympedia et Olympics.com concordent).'),
('jo-p1-036', 'jo', 'jo', 'number'::public.question_type, 'Combien de nations ont participé aux JO de Grenoble 1968, alors les Jeux d''hiver les plus internationaux de l''histoire ?', 'nations', 37, null, false, 'grenoble-nations', 'Olympedia (Grenoble 1968)', 'https://www.olympedia.org/editions/38', false, 2, 'published'::public.question_status, '2026-10-16', null, '37 nations, 1 160 athlètes (Olympics.com : 37 également).'),
('jo-p1-037', 'jo', 'jo', 'number'::public.question_type, 'En quelle année Chamonix a-t-elle accueilli les tout premiers Jeux olympiques d''hiver de l''histoire ?', '', 1924, null, true, 'chamonix-1924', 'Olympedia (Chamonix 1924)', 'https://www.olympedia.org/editions/29', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Du 25 janvier au 5 février 1924.'),
('jo-p1-038', 'jo', 'jo', 'number'::public.question_type, 'À quel âge Toni Nieminen a-t-il été sacré en saut à ski à Albertville 1992, plus jeune champion olympique individuel masculin des Jeux d''hiver (record en 2026) ?', 'ans', 16, null, false, 'nieminen', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/464370-youngest-individual-gold-medallist-at-a-winter-olympic-games-male', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', '16 ans et 261 jours (Guinness).'),
('jo-p1-039', 'jo', 'jo', 'number'::public.question_type, 'Combien de médailles la France a-t-elle gagnées aux Jeux paralympiques de Paris 2024, les plus grands Paralympiques jamais organisés en France ?', 'médailles', 75, null, false, 'france-paralympiques-2024', 'Comité international paralympique (tableau des médailles)', 'https://en.wikipedia.org/wiki/2024_Summer_Paralympics_medal_table', false, 2, 'published'::public.question_status, '2026-10-16', null, '19 or, 28 argent, 28 bronze ; 8e nation au tableau.'),
('jo-p1-040', 'jo', 'jo', 'number'::public.question_type, 'Combien d''épreuves comptaient les Jeux paralympiques de Paris 2024, l''édition au plus grand nombre de délégations de l''histoire ?', 'épreuves', 549, null, false, 'epreuves-paralympiques-2024', 'Comité international paralympique', 'https://www.paralympic.org/news/paris-2024-record-number-delegations-and-females-compete', false, 3, 'published'::public.question_status, '2026-10-16', null, '549 épreuves dans 22 sports, ~4 400 athlètes, record de 168 délégations.'),
('jo-p1-041', 'jo', 'jo', 'number'::public.question_type, 'En quelle année ont eu lieu à Rome les tout premiers Jeux paralympiques de l''histoire ?', '', 1960, null, true, 'premiers-paralympiques', 'Comité international paralympique', 'https://www.paralympic.org/rome-1960', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Du 18 au 25 septembre 1960, juste après les JO de Rome.'),
('jo-p1-042', 'jo', 'jo', 'number'::public.question_type, 'En quelle année a été fondé le CIO à la Sorbonne, la plus ancienne institution du mouvement olympique moderne ?', '', 1894, null, true, 'cio-fondation', 'CIO (Journée olympique)', 'https://www.olympics.com/ioc/olympic-day', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Le 23 juin 1894, à l''initiative de Pierre de Coubertin.'),
('jo-p1-043', 'jo', 'jo', 'number'::public.question_type, 'En quelle année Pierre de Coubertin a-t-il dessiné les anneaux olympiques, l''un des symboles les plus célèbres au monde ?', '', 1913, null, true, 'anneaux-olympiques', 'CIO', 'https://www.olympics.com/ioc/news/in-1913-pierre-de-coubertin-designed-one-of-the-world-s-most-famous-symbols', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Apparus en tête d''une lettre de Coubertin en 1913 ; premier drapeau aux Jeux en 1920.'),
('jo-p1-044', 'jo', 'jo', 'number'::public.question_type, 'En quelle année des femmes ont-elles participé pour la première fois aux Jeux olympiques, avec le premier titre féminin de l''histoire (Charlotte Cooper) ?', '', 1900, null, true, 'femmes-premiers-jo', 'Olympedia (Paris 1900)', 'https://www.olympedia.org/editions/2', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Paris 1900 ; Charlotte Cooper gagne le tournoi de tennis.'),
('jo-p1-045', 'jo', 'jo', 'number'::public.question_type, 'En quelle année a eu lieu le tout premier relais de la flamme olympique, d''Olympie à Berlin ?', '', 1936, null, true, 'relais-flamme-1936', 'CIO (FAQ)', 'https://www.olympics.com/ioc/faq/olympic-symbol-and-identity/when-was-the-first-olympic-torch-relay-held', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Du 20 juillet au 1er août 1936, 3 075 porteurs.'),
('jo-p1-046', 'jo', 'jo', 'number'::public.question_type, 'Combien de jours se sont étalées les épreuves des JO de Paris 1900, les plus longs Jeux jamais organisés en France ?', 'jours', 168, null, false, 'paris-1900-duree', 'Olympedia (liste des éditions)', 'https://www.olympedia.org/editions', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Du 14 mai au 28 octobre 1900 (168 jours, bornes incluses), dans le cadre de l''Exposition universelle. Pas un record mondial : Londres 1908 s''est étalé sur 188 jours.'),
('jo-p1-047', 'jo', 'jo', 'number'::public.question_type, 'Combien de minutes a duré la demi-finale de lutte Klein–Asikainen aux JO de 1912, le plus long combat de lutte de l''histoire ?', 'min', 700, null, false, 'lutte-1912', 'Olympedia (Martin Klein)', 'https://www.olympedia.org/athletes/59870', false, 3, 'published'::public.question_status, '2026-10-16', null, '11 h 40 min, en plein soleil à Stockholm ; Klein, épuisé, n''a pas pu disputer la finale.'),
('jo-p1-048', 'jo', 'jo', 'number'::public.question_type, 'Combien d''années Shizo Kanakuri a-t-il mis pour terminer le marathon olympique de 1912, le marathon le plus long de l''histoire ?', 'ans', 54, null, false, 'kanakuri', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/585341-longest-time-to-complete-a-marathon', false, 1, 'published'::public.question_status, '2026-10-16', null, '54 ans, 249 jours, 5 h 32 min 20 s 3 (parti en 1912, arrivé en 1967).'),
('jo-p1-049', 'jo', 'jo', 'number'::public.question_type, 'À quelle altitude se trouve Mexico, hôte en 1968 des Jeux d''été les plus élevés de l''histoire ?', 'm', 2240, null, false, 'mexico-altitude', 'Guinness World Records', 'https://www.guinnessworldrecords.es/world-records/113079-highest-altitude-summer-olympic-games', false, 2, 'published'::public.question_status, '2026-10-16', null, '2 240 m (Guinness : 2 250 m ; Olympics.com : 2 300 m — écarts < 3 %).'),
('jo-p1-050', 'jo', 'jo', 'number'::public.question_type, 'Combien d''années a-t-il fallu à Montréal pour rembourser la dette de ses JO de 1976, les plus ruineux de leur époque ?', 'ans', 30, null, false, 'montreal-dette', 'Wikipédia (Stade olympique de Montréal)', 'https://en.wikipedia.org/wiki/Olympic_Stadium_(Montreal)', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Dette soldée en novembre 2006, 30 ans après les Jeux.'),
('jo-p1-051', 'jo', 'jo', 'number'::public.question_type, 'À quel âge Queenie Newall a-t-elle été sacrée en tir à l''arc en 1908, la championne olympique la plus âgée de l''histoire (record en 2026) ?', 'ans', 53, null, false, 'newall', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/118879-oldest-summer-olympic-games-gold-medallist-female', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', '53 ans et 275 jours (Guinness).'),
('jo-p1-052', 'jo', 'jo', 'number'::public.question_type, 'Quel âge avait Nadia Comăneci quand elle a obtenu à Montréal 1976 le premier 10 de l''histoire de la gymnastique olympique ?', 'ans', 14, null, false, 'comaneci', 'Olympics.com', 'https://www.olympics.com/en/news/this-week-in-olympic-history-july-15-21-nadia-comaneci-scores-the-first-perfect-10-in-gymnastics', false, 1, 'published'::public.question_status, '2026-10-16', null, '18 juillet 1976, barres asymétriques.'),
('jo-p1-053', 'jo', 'jo', 'ranking'::public.question_type, 'Classe ces nations de la moins à la plus médaillée aux JO de Paris 2024', 'médailles', null, '[{"label":"Australie","value":53},{"label":"Grande-Bretagne","value":65},{"label":"Chine","value":91},{"label":"États-Unis","value":126}]'::jsonb, false, 'medailles-paris2024-nations', 'Olympics.com (tableau des médailles)', 'https://www.olympics.com/en/olympic-games/paris-2024/medals', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Totaux officiels : AUS 53, GBR 65, CHN 91, USA 126. France (64) volontairement exclue.'),
('jo-p1-054', 'jo', 'jo', 'ranking'::public.question_type, 'Classe ces éditions des JO d''été de celle qui a réuni le moins à celle qui a réuni le plus d''athlètes', 'athlètes', null, '[{"label":"Athènes 1896","value":176},{"label":"Paris 1900","value":1242},{"label":"Paris 1924","value":3255},{"label":"Mexico 1968","value":5558}]'::jsonb, false, 'participants-jo-ete', 'Olympedia (éditions)', 'https://www.olympedia.org/editions/8', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Chiffres Olympedia (1, 2, 8, 17). Olympics.com diverge sur 1896/1900 (241/997) mais l''ordre reste identique.'),
('jo-p1-055', 'jo', 'jo', 'ranking'::public.question_type, 'Classe ces Jeux d''hiver de celui qui comptait le moins à celui qui comptait le plus d''épreuves', 'épreuves', null, '[{"label":"Chamonix 1924","value":17},{"label":"Grenoble 1968","value":35},{"label":"Albertville 1992","value":57},{"label":"Milan-Cortina 2026","value":116}]'::jsonb, false, 'epreuves-jo-hiver', 'Olympedia (éditions)', 'https://www.olympedia.org/editions/72', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Olympedia : 17 (Olympics.com : 16), 35, 57, 116. Ordre sans ambiguïté.'),
('jo-p1-056', 'jo', 'jo', 'ranking'::public.question_type, 'Classe ces légendes olympiques de la moins à la plus titrée (médailles d''or, après Milan-Cortina 2026)', 'médailles d''or', null, '[{"label":"Usain Bolt","value":8},{"label":"Mark Spitz","value":9},{"label":"Johannes Høsflot Klæbo","value":11},{"label":"Michael Phelps","value":23}]'::jsonb, false, 'or-athletes-legendes', 'Olympedia (médailles par athlète)', 'https://www.olympedia.org/statistics/medal/athlete', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'Klæbo est devenu le plus titré des Jeux d''hiver avec 6 titres à Milan-Cortina (11 au total).'),
('jo-p1-057', 'jo', 'jo', 'ranking'::public.question_type, 'Classe ces sports de celui qui est entré le plus tôt à celui qui est entré le plus tard au programme olympique', 'année d''entrée', null, '[{"label":"Judo","value":1964},{"label":"Beach-volley","value":1996},{"label":"BMX","value":2008},{"label":"Breaking","value":2024}]'::jsonb, false, 'debuts-sports', 'Olympics.com (fiches sports)', 'https://www.olympics.com/en/sports/cycling-bmx-racing/', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Judo Tokyo 1964, beach-volley Atlanta 1996, BMX Pékin 2008, breaking Paris 2024.'),
('jo-p1-058', 'jo', 'jo', 'ranking'::public.question_type, 'Classe ces nations de la moins à la plus médaillée aux Jeux paralympiques de Paris 2024', 'médailles', null, '[{"label":"Brésil","value":89},{"label":"États-Unis","value":105},{"label":"Grande-Bretagne","value":124},{"label":"Chine","value":220}]'::jsonb, false, 'medailles-paralympiques-2024', 'Comité international paralympique (tableau des médailles)', 'https://en.wikipedia.org/wiki/2024_Summer_Paralympics_medal_table', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Totaux : BRA 89, USA 105, GBR 124, CHN 220 (certaines sources : 222/125, ordre inchangé).'),
('jo-p1-059', 'jo', 'jo', 'ranking'::public.question_type, 'Classe ces disciplines de celle qui distribuait le moins à celle qui distribuait le plus de titres à Paris 2024', 'épreuves', null, '[{"label":"Judo","value":15},{"label":"Lutte","value":18},{"label":"Natation (bassin)","value":35},{"label":"Athlétisme","value":48}]'::jsonb, false, 'epreuves-par-sport-paris2024', 'Olympedia (Paris 2024 par discipline)', 'https://www.olympedia.org/editions/63', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Décompte des épreuves Olympedia : judo 15 (dont l''équipe mixte), lutte 18, natation 35, athlétisme 48.'),
('jo-p1-060', 'jo', 'jo', 'ranking'::public.question_type, 'Classe ces nations de la moins à la plus médaillée aux JO d''hiver de Milan-Cortina 2026', 'médailles', null, '[{"label":"Allemagne","value":26},{"label":"Italie","value":30},{"label":"États-Unis","value":33},{"label":"Norvège","value":41}]'::jsonb, false, 'medailles-milan-cortina', 'Olympics.com (tableau des médailles)', 'https://www.olympics.com/en/milano-cortina-2026/medals', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Totaux finaux : GER 26, ITA 30, USA 33, NOR 41 (record de médailles pour une nation aux JO d''hiver). France (23) exclue.')
